"use client";

import React from 'react';
import { useNavigate } from 'react-router-dom';
import { X, Phone, Mail, MapPin, Calendar, Home } from 'lucide-react';
import Avatar from '@/components/ui/Avatar';

interface ClientProfileModalProps {
    isOpen: boolean;
    onClose: () => void;
    clientName: string;
    avatar?: string;
    clientId?: string;
    email?: string;
    phone?: string;
    location?: string;
    memberSince?: string;
    interestedIn?: string;
}

const ClientProfileModal: React.FC<ClientProfileModalProps> = ({
    isOpen,
    onClose,
    clientName,
    avatar,
    clientId,
    email,
    phone,
    location,
    memberSince,
    interestedIn,
}) => {
    const navigate = useNavigate();

    if (!isOpen) return null;

    const handleViewHistory = () => {
        navigate(`/manager/leads`); // Using leads page as proxy for client history for now
    };

    const handleMessage = () => {
        navigate('/manager/messages');
    };

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white dark:bg-gray-900 rounded-2xl shadow-xl w-full max-w-md overflow-hidden relative animate-in zoom-in-95 duration-200">
                {/* Header Background */}
                <div className="h-24 bg-gradient-to-r from-blue-500 to-indigo-600"></div>

                {/* Close Button */}
                <button
                    onClick={onClose}
                    className="absolute top-4 right-4 bg-black/20 hover:bg-black/40 text-white rounded-full p-1 transition-colors"
                >
                    <X className="w-5 h-5" />
                </button>

                {/* Profile Content */}
                <div className="px-6 pb-6 mt-[-3rem]">
                    <div className="flex flex-col items-center">
                        {/* Avatar */}
                        <div className="mb-4 rounded-full border-4 border-white dark:border-gray-900 shadow-lg">
                            <Avatar
                                userId={clientId}
                                src={avatar}
                                name={clientName}
                                alt={clientName}
                                size="xl"
                                className="block"
                            />
                        </div>

                        <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-1">{clientName}</h2>
                        <div className="flex items-center gap-1 text-sm text-gray-500 dark:text-gray-400 mb-6">
                            <MapPin className="w-4 h-4" />
                            <span>{location || 'Location not available'}</span>
                        </div>

                        {/* Info Grid */}
                        <div className="w-full grid grid-cols-2 gap-4 mb-6">
                            <div className="bg-gray-50 dark:bg-gray-800 p-3 rounded-xl border border-gray-100 dark:border-gray-700">
                                <div className="flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400 mb-1">
                                    <Phone className="w-3 h-3" />
                                    <span>Phone</span>
                                </div>
                                <p className="font-medium text-sm text-gray-900 dark:text-white">{phone || 'Not available'}</p>
                            </div>
                            <div className="bg-gray-50 dark:bg-gray-800 p-3 rounded-xl border border-gray-100 dark:border-gray-700">
                                <div className="flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400 mb-1">
                                    <Mail className="w-3 h-3" />
                                    <span>Email</span>
                                </div>
                                <p className="font-medium text-sm text-gray-900 dark:text-white truncate">{email || 'Not available'}</p>
                            </div>
                            <div className="bg-gray-50 dark:bg-gray-800 p-3 rounded-xl border border-gray-100 dark:border-gray-700">
                                <div className="flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400 mb-1">
                                    <Calendar className="w-3 h-3" />
                                    <span>Member Since</span>
                                </div>
                                <p className="font-medium text-sm text-gray-900 dark:text-white">{memberSince || 'Not available'}</p>
                            </div>
                            <div className="bg-gray-50 dark:bg-gray-800 p-3 rounded-xl border border-gray-100 dark:border-gray-700">
                                <div className="flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400 mb-1">
                                    <Home className="w-3 h-3" />
                                    <span>Interested In</span>
                                </div>
                                <p className="font-medium text-sm text-gray-900 dark:text-white">{interestedIn || 'Not available in this view'}</p>
                            </div>
                        </div>

                        {/* Actions */}
                        <div className="w-full flex gap-3">
                            <button
                                onClick={handleViewHistory}
                                className="flex-1 bg-orange-500 hover:bg-orange-600 text-white py-2.5 rounded-lg font-medium transition-colors"
                            >
                                View History
                            </button>
                            <button
                                onClick={handleMessage}
                                className="flex-1 bg-white hover:bg-gray-50 dark:bg-gray-800 dark:hover:bg-gray-700 border border-gray-100 dark:border-gray-700 text-gray-700 dark:text-gray-200 py-2.5 rounded-lg font-medium transition-colors"
                            >
                                Message
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ClientProfileModal;

